{() => setRecurringDays(days => {
    if (days.includes(d.v)) {
        return days.filter(x => x !== d.v);
    }
    const next = [...days, d.v];
    return next.sort((a, b) => ((a === 0 ? 7 : a) - (b === 0 ? 7 : b)));
})}

